package cn.song.mybatisplus.visualizer.model;

import java.util.Objects;

/**
 * 批量列（T-M23-04，勾选行数据）。
 *
 * @param columnName 数据库列名
 * @param source     参数来源（entity.列名，面板标签与参数行 key）
 * @param quote      回填引号提示（ParamQuote 按列类型判定）
 * @param checked    默认勾选态（INSERT 主键且 IdType.AUTO → false，其余 true）
 * @param autoGenerated 自增/数据库生成列（O-52）：INSERT 的<b>活跃列</b>含本类列时过
 *                  {@code Dialect.renderInsertWrapper}（SQL Server {@code SET IDENTITY_INSERT}）；
 *                  默认 false = 无自增信息 → 不包装（既有构造点零改动，产物逐字节不变）
 * @param fill      MP 自动填充模式（R48：@TableField(fill=FieldFill.X) 解析值，角标/手填
 *                  模拟值数据面；非填充列恒 null）
 */
public final class BatchColumn {
    private final String columnName;
    private final String source;
    private final Boolean quote;
    private final boolean checked;
    private final boolean autoGenerated;
    private final String fill;

    public BatchColumn(String columnName, String source, Boolean quote, boolean checked, boolean autoGenerated,
                       String fill) {
        this.columnName = columnName;
        this.source = source;
        this.quote = quote;
        this.checked = checked;
        this.autoGenerated = autoGenerated;
        this.fill = fill;
    }

    public BatchColumn(String columnName, String source, Boolean quote, boolean checked, boolean autoGenerated) {
        this(columnName, source, quote, checked, autoGenerated, null);
    }

    public BatchColumn(String columnName, String source, Boolean quote, boolean checked) {
        this(columnName, source, quote, checked, false, null);
    }

    public String getColumnName() {
        return columnName;
    }

    public String getSource() {
        return source;
    }

    public Boolean getQuote() {
        return quote;
    }

    public boolean isChecked() {
        return checked;
    }

    public boolean getChecked() {
        return checked;
    }

    public boolean isAutoGenerated() {
        return autoGenerated;
    }

    public String getFill() {
        return fill;
    }

    public BatchColumn copy(String columnName, String source, Boolean quote, boolean checked, boolean autoGenerated,
                            String fill) {
        return new BatchColumn(columnName, source, quote, checked, autoGenerated, fill);
    }

    public BatchColumn copy(String columnName, String source, Boolean quote, boolean checked, boolean autoGenerated) {
        return new BatchColumn(columnName, source, quote, checked, autoGenerated, fill);
    }

    public BatchColumn copy(String columnName, String source, Boolean quote, boolean checked) {
        return new BatchColumn(columnName, source, quote, checked, autoGenerated, fill);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof BatchColumn)) {
            return false;
        }
        BatchColumn that = (BatchColumn) o;
        return checked == that.checked
                && autoGenerated == that.autoGenerated
                && Objects.equals(columnName, that.columnName)
                && Objects.equals(source, that.source)
                && Objects.equals(quote, that.quote)
                && Objects.equals(fill, that.fill);
    }

    @Override
    public int hashCode() {
        return Objects.hash(columnName, source, quote, checked, autoGenerated, fill);
    }

    @Override
    public String toString() {
        return "BatchColumn(columnName=" + columnName + ", source=" + source + ", quote=" + quote
                + ", checked=" + checked + ", autoGenerated=" + autoGenerated + ", fill=" + fill + ")";
    }
}
